        if not pre2:
            return -1

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all digits
            is_num1 = id1.isdigit()
