                # Both non-numeric, compare by ASCII order
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        # All shared identifiers are equal, fewer sorts first
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

