        # Return tuple for sorting
        # (major, minor, patch, prerelease_sort_key)
        # For prerelease, we need to handle the comparison specially
        # Use a tuple where non-prerelease sorts after prerelease
        if not prerelease:
            # (1, ()) means no prerelease, sorts after prerelease (0, ...)
            prerelease_key = (1,)
